import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for square matrix multiplication
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block row and column
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Global row and column for the current thread
    int row = blockRow * TILE_SIZE + threadIdx.y;
    int col = blockCol * TILE_SIZE + threadIdx.x;

    // Shared memory for tiles of A and B
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    float Cvalue = 0.0f;

    // Loop over phases
    int num_phases = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int phase = 0; phase < num_phases; ++phase) {
        // Load tile from global memory to shared memory
        // Calculate global indices for loading A and B into shared memory
        int A_col_global = phase * TILE_SIZE + threadIdx.x;
        int B_row_global = phase * TILE_SIZE + threadIdx.y;

        // Check bounds before loading
        if (row < N && A_col_global < N) {
            sA[threadIdx.y][threadIdx.x] = A[row * N + A_col_global];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        if (B_row_global < N && col < N) {
            sB[threadIdx.y][threadIdx.x] = B[B_row_global * N + col];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        __syncthreads(); // Wait for all threads to load their data

        // Perform matrix multiplication for the current tile
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            Cvalue += sA[threadIdx.y][k] * sB[k][threadIdx.x];
        }

        __syncthreads(); // Wait for all threads to finish computation on shared data
    }

    // Write result to global memory, check bounds
    if (row < N && col < N) {
        C[row * N + col] = Cvalue;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Input tensors must be 2D.");
    TORCH_CHECK(A.size(0) == A.size(1) && B.size(0) == B.size(1), "Input tensors must be square matrices.");
    TORCH_CHECK(A.size(0) == B.size(0), "Input matrices must have the same dimension N.");
    TORCH_CHECK(A.is_cuda && B.is_cuda, "Input tensors must be on CUDA device.");

    int N = A.size(0);

    // Ensure inputs are contiguous
    A = A.contiguous();
    B = B.contiguous();

    // Create output tensor with same options
    auto C = torch::zeros({N, N}, A.options());

    // Calculate grid and block dimensions
    dim3 block_size(TILE_SIZE, TILE_SIZE);
    dim3 num_blocks((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<num_blocks, block_size>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    // Check for CUDA errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error: %s\n", cudaGetErrorString(err));
    }

    return C;
}
"""

matmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code
matmul_extension = load_inline(
    name="matmul_extension",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags
    extra_ldflags=[""],
    with_cuda=True,
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul_cuda = matmul_extension

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul_cuda.matmul_cuda(A, B)
